INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_05','V386','阮明',5,'新学期课程表全部排满白天晚上，完全抽不出空余时间兼顾兼职工作。','xīn xué qī kè chéng biǎo quán bù pái mǎn bái tiān wǎn shàng， wán quán chōu bù chū kòng yú shí jiān jiān gù jiān zhí gōng zuò。','Thời khóa biểu học kỳ mới của em kín hết cả ngày lẫn tối, không thể nào sắp xếp thời gian làm thêm được nữa.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_06','V386','店长',6,'我能理解留学生课业压力大，直接按三十天标准离职时间执行对你压力太大。','wǒ néng lǐ jiě liú xué shēng kè yè yā lì dà， zhí jiē àn sān shí tiān biāo zhǔn lí zhí shí jiān zhí xíng duì nǐ yā lì tài dà。','Chị hiểu áp lực học hành của du học sinh rất lớn, nếu bắt em phải làm đủ ba mươi ngày theo tiêu chuẩn thì cũng quá sức với em.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_07','V386','阮明',7,'我这段时间可以全力做好客户对接、货品盘点等全部工作交接。','wǒ zhè duàn shí jiān kě yǐ quán lì zuò hào kè hù duì jiē、 huò pǐn pán diǎn děng quán bù gōng zuò jiāo jiē。','Trong thời gian này em có thể dồn hết sức để bàn giao đầy đủ, từ kết nối khách hàng đến kiểm kê hàng hóa.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_08','V386','店长',8,'结合门店近期人手充足的现状，我向上级人事申请，最多协调缩短到二十天离职周期。','jié hé mén diàn jìn qī rén shǒu chōng zú de xiàn zhuàng， wǒ xiàng shàng jí rén shì shēn qǐng， zuì duō xié tiáo suō duǎn dào èr shí tiān lí zhí zhōu qī。','Xét tình hình gần đây cửa hàng cũng đủ người, chị sẽ xin bên nhân sự, cố gắng thu xếp rút xuống còn hai mươi ngày.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_09','V386','阮明',9,'二十天的周期我完全可以接受，这段时间我逐项梳理所有工作内容做好交接。','èr shí tiān de zhōu qī wǒ wán quán kě yǐ jiē shòu， zhè duàn shí jiān wǒ zhú xiàng shū lǐ suǒ yǒu gōng zuò nèi róng zuò hǎo jiāo jiē。','Hai mươi ngày thì em hoàn toàn chấp nhận được, thời gian đó em sẽ rà soát từng phần công việc để bàn giao cho chu đáo.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_10','V386','店长',10,'今天填写纸质离职申请表，我签字之后统一交给人事部门存档备案。','jīn tiān tián xiě zhǐ zhì lí zhí shēn qǐng biǎo， wǒ qiān zì zhī hòu tǒng yī jiāo gěi rén shì bù mén cún dàng bèi àn。','Hôm nay em điền vào đơn xin nghỉ việc bản giấy, chị ký xong sẽ nộp lên phòng nhân sự lưu hồ sơ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_11','V386','阮明',11,'交接清单我每天整理一部分，离职当天完整交给接替岗位的同事。','jiāo jiē qīng dān wǒ měi tiān zhěng lǐ yī bù fèn， lí zhí dàng tiān wán zhěng jiāo gěi jiē tì gǎng wèi de tóng shì。','Danh sách bàn giao em sẽ soạn dần mỗi ngày một phần, đến ngày nghỉ việc sẽ giao đầy đủ cho người kế nhiệm.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_12','V386','店长',12,'交接过程中有不清楚的地方随时来办公室找我沟通。','jiāo jiē guò chéng zhōng yǒu bù qīng chǔ de dì fāng suí shí lái bàn gōng shì zhǎo wǒ gōu tōng。','Trong quá trình bàn giao có chỗ nào chưa rõ thì cứ lên văn phòng tìm chị trao đổi nhé.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_13','V386','阮明',13,'麻烦店长帮忙审批这份离职申请，这段时间也多谢门店所有人照顾我。','má fán diàn zhǎng bāng máng shěn pī zhè fèn lí zhí shēn qǐng， zhè duàn shí jiān yě duō xiè mén diàn suǒ yǒu rén zhào gù wǒ。','Phiền chị duyệt giúp em đơn xin nghỉ này, cũng cảm ơn mọi người ở cửa hàng đã quan tâm giúp đỡ em trong thời gian qua.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_14','V386','店长',14,'没事，学业为重，后续有空闲假期也欢迎再来短期兼职。','méi shì， xué yè wèi zhòng， hòu xù yǒu kòng xián jià qī yě huān yíng zài lái duǎn qī jiān zhí。','Không sao đâu, việc học là quan trọng nhất, sau này rảnh kỳ nghỉ nào thì cứ quay lại làm thêm thời vụ nhé.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_15','V386','阮明',15,'十分感谢您通融调整离职周期！','shí fēn gǎn xiè nín tōng róng tiáo zhěng lí zhí zhōu qī！','Em cảm ơn chị rất nhiều vì đã linh động điều chỉnh thời gian nghỉ việc cho em!',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT387','S127','Hỏi quy định giờ làm tối đa cho sinh viên quốc tế',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V387','SIT387','P1','suon_se','chinh_thuc',NULL,'中国法律明确规定外籍留学生务工时长，超时务工将影响签证续签，学校会定期核查兼职情况。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L387_01','V387','阮明',1,'老师您好，我想咨询留学生校内、校外兼职时长限制。','lǎo shī nín hǎo， wǒ xiǎng zī xún liú xué shēng xiào nèi、 xiào wài jiān zhí shí cháng xiàn zhì。','Chào thầy/cô, em muốn hỏi về quy định giới hạn thời gian làm thêm trong và ngoài trường dành cho du học sinh ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L387_02','V387','国际处老师',2,'学期内每周打工总时长不能超过二十小时哦。','xué qī nèi měi zhōu dǎ gōng zǒng shí cháng bù néng chāo guò èr shí xiǎo shí ó。','Trong học kỳ, tổng thời gian làm thêm mỗi tuần không được vượt quá hai mươi giờ đâu.','AM03') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L387_03','V387','阮明',3,'寒暑假期间，时长限制会适当放宽一些吗？','hán shǔ jià qī jiān， shí cháng xiàn zhì huì shì dàng fàng kuān yī xiē ma？','Vậy vào kỳ nghỉ hè và nghỉ đông, giới hạn thời gian có được nới lỏng hơn một chút không ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L387_04','V387','国际处老师',4,'假期每周最多四十小时，超出属于违规务工呢。','jià qī měi zhōu zuì duō sì shí xiǎo shí， chāo chū shǔ yú wéi guī wù gōng ne。','Vào kỳ nghỉ thì tối đa bốn mươi giờ mỗi tuần, vượt quá mức đó là lao động trái quy định đấy.','AM04') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L387_05','V387','阮明',5,'超时打工会不会影响我的签证续办审核？','chāo shí dǎ gōng huì bú huì yǐng xiǎng wǒ de qiān zhèng xù bàn shěn hé？','Nếu làm thêm quá giờ thì có ảnh hưởng đến việc xét gia hạn visa của em không ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L387_06','V387','国际处老师',6,'会有影响，出入境管理局会核查务工时长记录。','huì yǒu yǐng xiǎng， chū rù jìng guǎn lǐ jú huì hé chá wù gōng shí cháng jì lù。','Có ảnh hưởng đấy, cục quản lý xuất nhập cảnh sẽ kiểm tra hồ sơ ghi nhận thời gian làm thêm.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L387_07','V387','阮明',7,'我清楚规定了，一定会严格控制上班时长。','wǒ qīng chǔ guī dìng le， yí dìng huì yán gé kòng zhì shàng bān shí cháng。','Em đã hiểu rõ quy định rồi, em nhất định sẽ kiểm soát chặt chẽ thời gian làm việc của mình.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT388','S127','Trao đổi ca làm việc với đồng nghiệp',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V388','SIT388','P1','twist','tuy_y',NULL,'兼职员工私下换班必须告知主管登记，避免岗位无人值守，产生运营问题。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L388_01','V388','阮明',1,'小秦，我周四下午有汉语测验，能和你互换班次吗？','xiǎo qín， wǒ zhōu sì xià wǔ yǒu hàn yǔ cè yàn， néng hé nǐ hù huàn bān cì ma？','Tiểu Tần ơi, chiều thứ Năm này mình có bài kiểm tra tiếng Hán, cậu đổi ca với mình được không?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L388_02','V388','小秦',2,'我周四全天有社团活动，那天也没办法上班嘛。','wǒ zhōu sì quán tiān yǒu shè tuán huó dòng， nà tiān yě méi bàn fǎ shàng bān ma。','Thứ Năm cả ngày mình có hoạt động câu lạc bộ, hôm đó mình cũng không đi làm được đâu.','AM09') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L388_03','V388','阮明',3,'原来是这样，那周五的班次你方便和我调换不？','yuán lái shì zhè yàng， nà zhōu wǔ de bān cì nǐ fāng biàn hé wǒ diào huàn bù？','À ra vậy, thế ca thứ Sáu cậu có tiện đổi cho mình không?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L388_04','V388','小秦',4,'周五我空闲，我们调换之后跟店长报备一下就行。','zhōu wǔ wǒ kòng xián， wǒ men diào huàn zhī hòu gēn diàn zhǎng bào bèi yī xià jiù xíng。','Thứ Sáu mình rảnh, đổi xong tụi mình báo cho quản lý một tiếng là được.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L388_05','V388','阮明',5,'太好了，调换班次需要填写纸质调换申请单吗？','tài hǎo le， diào huàn bān cì xū yào tián xiě zhǐ zhì diào huàn shēn qǐng dān ma？','Tuyệt quá, đổi ca thế này có cần điền đơn giấy xin đổi ca không?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L388_06','V388','小秦',6,'不用，微信跟店长说一声登记备案就可以。','bù yòng， wēi xìn gēn diàn zhǎng shuō yī shēng dēng jì bèi àn jiù kě yǐ。','Không cần đâu, nhắn WeChat báo quản lý một câu để ghi nhận lại là xong.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L388_07','V388','阮明',7,'太谢谢你，解决了我的难题。','tài xiè xiè nǐ， jiě jué le wǒ de nán tí。','Cảm ơn cậu nhiều lắm, cậu giải quyết giúp mình vấn đề nan giải luôn đó.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT389','S127','Báo cáo sự cố trong ca làm với quản lý',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V389','SIT389','P1','suon_se','ban_chinh_thuc',NULL,'服务行业工作中出现客户突发状况，员工第一时间上报主管并留存记录，是标准工作流程。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L389_01','V389','阮明',1,'主管，刚刚上课出现突发情况，我来跟您汇报一下。','zhǔ guǎn， gāng gāng shàng kè chū xiàn tū fā qíng kuàng， wǒ lái gēn nín huì bào yī xià。','Thưa quản lý, vừa nãy trong giờ dạy xảy ra sự việc bất ngờ, em xin báo cáo lại với anh/chị.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L389_02','V389','主管',2,'别着急，慢慢说，课堂上发生什么意外了吧？','bié zháo jí， màn màn shuō， kè táng shàng fā shēng shén me yì wài le ba？','Đừng gấp, cứ từ từ kể, trong lớp xảy ra chuyện gì vậy?','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L389_03','V389','阮明',3,'一名小朋友身体不舒服，家长临时赶来把孩子接走了呢。','yī míng xiǎo péng yǒu shēn tǐ bù shū fú， jiā zhǎng lín shí gǎn lái bǎ hái zi jiē zǒu le ne。','Có một bé bị khó chịu trong người, phụ huynh vội đến đón bé về rồi ạ.','AM04') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L389_04','V389','主管',4,'孩子有没有出现发烧、呕吐这类严重不适症状？','hái zi yǒu méi yǒu chū xiàn fā shāo、 ǒu tù zhè lèi yán zhòng bù shì zhèng zhuàng？','Bé có bị sốt, nôn ói hay có triệu chứng nghiêm trọng nào khác không?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L389_05','V389','阮明',5,'只是轻微头晕，休息片刻就好转，家长已经带离校区。','zhǐ shì qīng wēi tóu yūn， xiū xī piàn kè jiù hǎo zhuǎn， jiā zhǎng yǐ jīng dài lí xiào qū。','Chỉ hơi chóng mặt nhẹ thôi, nghỉ một lát là đỡ, phụ huynh đã đưa bé rời khỏi trường rồi ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L389_06','V389','主管',6,'记录好学生信息，后续跟进询问孩子身体状况。','jì lù hào xué shēng xìn xī， hòu xù gēn jìn xún wèn hái zi shēn tǐ zhuàng kuàng。','Em ghi lại thông tin của học sinh, sau đó tiếp tục theo dõi hỏi thăm tình hình sức khỏe của bé nhé.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L389_07','V389','阮明',7,'好，我马上整理情况记录，同步发给您查看。','hǎo， wǒ mǎ shàng zhěng lǐ qíng kuàng jì lù， tóng bù fā gěi nín chá kàn。','Vâng, em sẽ lập tức tổng hợp lại tình hình và gửi cho anh/chị xem ngay.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT390','S127','Xin thư giới thiệu từ nơi thực tập',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V390','SIT390','P1','twist','chinh_thuc',NULL,'企业开具实习推荐信加盖公章需行政部门审核，私人手写无公章的推荐信不具备官方证明效力。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L390_01','V390','阮明',1,'领导您好，我的实习周期即将结束，想申请一份实习推荐信。','lǐng dǎo nín hǎo， wǒ de shí xí zhōu qī jí jiāng jié shù， xiǎng shēn qǐng yī fèn shí xí tuī jiàn xìn。','Chào anh, kỳ thực tập của em sắp kết thúc rồi, em muốn xin một thư giới thiệu thực tập ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L390_02','V390','负责人',2,'可以，推荐信用于升学还是后续求职使用呢？','kě yǐ， tuī jiàn xìn yòng yú shēng xué hái shì hòu xù qiú zhí shǐ yòng ne？','Được chứ, thư giới thiệu này em dùng để học tiếp lên hay để xin việc sau này?','AM04') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L390_03','V390','阮明',3,'用于境外深造申请，需要加盖公司官方公章对吧？','yòng yú jìng wài shēn zào shēn qǐng， xū yào jiā gài gōng sī guān fāng gōng zhāng duì ba？','Em dùng để nộp hồ sơ du học nước ngoài, cần đóng dấu chính thức của công ty phải không ạ?','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L390_04','V390','负责人',4,'推荐信内容我可以撰写，但公章需要行政部门统一审批嘛。','tuī jiàn xìn nèi róng wǒ kě yǐ zhuàn xiě， dàn gōng zhāng xū yào xíng zhèng bù mén tǒng yī shěn pī ma。','Nội dung thư giới thiệu anh có thể viết cho em, nhưng việc đóng dấu thì cần phòng hành chính duyệt thống nhất nhé.','AM09') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L390_05','V390','阮明',5,'审批流程大概需要几天，我下周就要提交申请材料。','shěn pī liú chéng dà gài xū yào jǐ tiān， wǒ xià zhōu jiù yào tí jiāo shēn qǐng cái liào。','Quy trình duyệt khoảng bao nhiêu ngày ạ, tuần sau em phải nộp hồ sơ rồi.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L390_06','V390','负责人',6,'三天内完成审批盖章，到时候我通知你来领取。','sān tiān nèi wán chéng shěn pī gài zhāng， dào shí hòu wǒ tōng zhī nǐ lái lǐng qǔ。','Trong ba ngày sẽ hoàn tất duyệt và đóng dấu, lúc đó anh sẽ báo em đến lấy.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L390_07','V390','阮明',7,'麻烦领导费心帮忙，非常感谢。','má fán lǐng dǎo fèi xīn bāng máng， fēi cháng gǎn xiè。','Phiền anh giúp đỡ em, em cảm ơn anh rất nhiều ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT391','S129','Xin cấp bảng điểm chính thức',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V391','SIT391','P1','twist','ban_chinh_thuc',NULL,'留学生用于出境、升学的成绩单必须由学校教务盖章，电子版文件不具备官方效力。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L391_01','V391','阮明',1,'老师您好，我毕业需要正式成绩单，想申请打印几份。','lǎo shī nín hǎo， wǒ bì yè xū yào zhèng shì chéng jì dān， xiǎng shēn qǐng dǎ yìn jǐ fèn。','Chào thầy/cô, em sắp tốt nghiệp nên cần bảng điểm chính thức, em muốn xin in vài bản ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L391_02','V391','教务老师',2,'没问题，填好这份申请表，带上你的护照原件哦。','méi wèn tí， tián hǎo zhè fèn shēn qǐng biǎo， dài shàng nǐ de hù zhào yuán jiàn ó。','Không vấn đề gì, em điền vào đơn này, nhớ mang theo hộ chiếu bản gốc nhé.','AM03') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L391_03','V391','阮明',3,'申请表我已经填完了，但是护照昨天拿去办签证了嘛。','shēn qǐng biǎo wǒ yǐ jīng tián wán le， dàn shì hù zhào zuó tiān ná qù bàn qiān zhèng le ma。','Đơn em điền xong rồi ạ, nhưng hộ chiếu hôm qua em mang đi làm visa mất rồi ạ.','AM09') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L391_04','V391','教务老师',4,'没有证件不能办理，你改天带护照再来登记吧。','méi yǒu zhèng jiàn bù néng bàn lǐ， nǐ gǎi tiān dài hù zhào zài lái dēng jì ba。','Không có giấy tờ thì không làm được, hôm khác em mang hộ chiếu đến đăng ký lại nhé.','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L391_05','V391','阮明',5,'那我明天一早把护照带过来，当天就能拿到成绩单吗？','nà wǒ míng tiān yī zǎo bǎ hù zhào dài guò lái， dàng tiān jiù néng ná dào chéng jì dān ma？','Vậy sáng mai em mang hộ chiếu đến sớm, có thể nhận bảng điểm ngay trong ngày không ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L391_06','V391','教务老师',6,'纸质成绩单当场打印盖章，不用额外等候。','zhǐ zhì chéng jì dān dāng chǎng dǎ yìn gài zhāng， bù yòng é wài děng hòu。','Bảng điểm giấy sẽ in và đóng dấu ngay tại chỗ, không cần chờ đợi thêm đâu.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L391_07','V391','阮明',7,'好，辛苦老师，我明天准时过来办理。','hǎo， xīn kǔ lǎo shī， wǒ míng tiān zhǔn shí guò lái bàn lǐ。','Vâng, cảm ơn thầy/cô đã vất vả giúp đỡ, mai em sẽ đến đúng giờ để làm thủ tục.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT392','S129','Xin cấp bằng tốt nghiệp và công chứng',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V392','SIT392','P1','suon_se','chinh_thuc',NULL,'外国留学生回国使用国内学历证件，必须办理涉外公证，境外机构才认可学历效力。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L392_01','V392','阮明',1,'您好，我课程全部修完，来领取毕业证并申请校内公证。','nín hǎo， wǒ kè chéng quán bù xiū wán， lái lǐng qǔ bì yè zhèng bìng shēn qǐng xiào nèi gōng zhèng。','Chào anh/chị, em đã hoàn thành hết các môn học rồi, em đến nhận bằng tốt nghiệp và xin công chứng trong trường ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L392_02','V392','工作人员',2,'先核对你的全部考勤和缴费记录，没有欠费才能办理呢。','xiān hé duì nǐ de quán bù kǎo qín hé jiǎo fèi jì lù， méi yǒu qiàn fèi cái néng bàn lǐ ne。','Để tôi kiểm tra lại toàn bộ hồ sơ điểm danh và học phí của em đã, không còn nợ gì thì mới làm được nhé.','AM04') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L392_03','V392','阮明',3,'学费、住宿费我都按时交清，没有任何欠费记录。','xué fèi、 zhù sù fèi wǒ dōu àn shí jiāo qīng， méi yǒu rèn hé qiàn fèi jì lù。','Học phí và tiền ký túc xá em đều đóng đúng hạn, không có khoản nào còn nợ cả ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L392_04','V392','工作人员',4,'毕业证当场发放，公证文件三个工作日后可取。','bì yè zhèng dāng chǎng fā fàng， gōng zhèng wén jiàn sān gè gōng zuò rì hòu kě qǔ。','Bằng tốt nghiệp sẽ cấp ngay tại chỗ, còn giấy công chứng thì sau ba ngày làm việc mới lấy được.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L392_05','V392','阮明',5,'公证文件可以多打印两份，方便我带回越南使用吧？','gōng zhèng wén jiàn kě yǐ duō dǎ yìn liǎng fèn， fāng biàn wǒ dài huí yuè nán shǐ yòng ba？','Giấy công chứng em xin in thêm hai bản nữa được không ạ, để tiện mang về Việt Nam sử dụng?','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L392_06','V392','工作人员',6,'没问题，每份公证只收取基础工本费。','méi wèn tí， měi fèn gōng zhèng zhǐ shōu qǔ jī chǔ gōng běn fèi。','Không vấn đề gì, mỗi bản công chứng chỉ thu phí làm hồ sơ cơ bản thôi.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L392_07','V392','阮明',7,'麻烦您帮忙办理，这份材料对我后续深造很重要。','má fán nín bāng máng bàn lǐ， zhè fèn cái liào duì wǒ hòu xù shēn zào hěn zhòng yào。','Phiền anh/chị giúp em làm thủ tục, hồ sơ này rất quan trọng cho việc học lên sau này của em.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT393','S130','Làm thủ tục trả phòng ký túc xá',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V393','SIT393','P1','twist','ban_chinh_thuc',NULL,'高校宿舍退房会逐一清点室内设施，人为造成大面积破损，学校会从住宿押金中扣除维修费。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L393_01','V393','阮明',1,'阿姨，我今天来办宿舍退房，麻烦检查一下房间。','ā yí， wǒ jīn tiān lái bàn sù shè tuì fáng， má fán jiǎn chá yī xià fáng jiān。','Cô ơi, hôm nay con đến trả phòng ký túc xá, phiền cô kiểm tra giúp phòng con nhé.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L393_02','V393','宿管阿姨',2,'我看看桌椅、墙面和电器，破损会扣押金哈。','wǒ kàn kàn zhuō yǐ、 qiáng miàn hé diàn qì， pò sǔn huì kòu yā jīn hā。','Để cô xem bàn ghế, tường và đồ điện, hỏng gì là bị trừ tiền cọc đó nha.','AM06') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L393_03','V393','阮明',3,'我平时很爱惜房间，只有书桌边角有一点小划痕嘛。','wǒ píng shí hěn ài xī fáng jiān， zhǐ yǒu shū zhuō biān jiǎo yǒu yì diǎn xiǎo huà hén ma。','Con giữ gìn phòng cẩn thận lắm, chỉ có góc bàn học bị trầy nhẹ một chút xíu thôi ạ.','AM09') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L393_04','V393','宿管阿姨',4,'轻微划痕不影响，不需要扣除押金。','qīng wēi huà hén bù yǐng xiǎng， bù xū yào kòu chú yā jīn。','Trầy nhẹ vậy thì không sao, không cần trừ tiền cọc đâu.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L393_05','V393','阮明',5,'那我的行李可以暂时放在楼道等同学帮忙搬运吗？','nà wǒ de xíng lǐ kě yǐ zàn shí fàng zài lóu dào děng tóng xué bāng máng bān yùn ma？','Vậy hành lý của con có thể để tạm ở hành lang chờ bạn đến phụ khiêng được không cô?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L393_06','V393','宿管阿姨',6,'短时间放置没问题，不要堵塞消防通道就行。','duǎn shí jiān fàng zhì méi wèn tí， bú yào dǔ sè xiāo fáng tōng dào jiù xíng。','Để tạm một lát thì không sao, chỉ cần đừng chắn lối thoát hiểm là được.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L393_07','V393','阮明',7,'太感谢阿姨通融，我收拾完立刻离开宿舍楼。','tài gǎn xiè ā yí tōng róng， wǒ shōu shí wán lì kè lí kāi sù shè lóu。','Con cảm ơn cô đã thông cảm nhiều lắm, con dọn xong là rời khỏi ký túc xá ngay ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT394','S130','Thanh lý hợp đồng thuê nhà ngoài',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V394','SIT394','P1','suon_se','ban_chinh_thuc',NULL,'提前退租需和房东当面清点房屋物品，确认无损坏、无欠费后，房东才会全额返还租房押金。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L394_01','V394','阮明',1,'房东您好，我马上毕业回国，想提前终止租房合同。','fáng dōng nín hǎo， wǒ mǎ shàng bì yè huí guó， xiǎng tí qián zhōng zhǐ zū fáng hé tóng。','Chào chủ nhà, em sắp tốt nghiệp về nước rồi, em muốn xin kết thúc hợp đồng thuê nhà sớm ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L394_02','V394','房东',2,'可以，我们按合同约定清点家具，结清水电杂费吧。','kě yǐ， wǒ men àn hé tóng yuē dìng qīng diǎn jiā jù， jié qīng shuǐ diàn zá fèi ba。','Được thôi, mình kiểm kê đồ đạc theo hợp đồng rồi thanh toán nốt tiền điện nước nhé.','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L394_03','V394','阮明',3,'所有家具完好无损，水电费我已经全部缴清了呢。','suǒ yǒu jiā jù wán hǎo wú sǔn， shuǐ diàn fèi wǒ yǐ jīng quán bù jiǎo qīng le ne。','Đồ đạc còn nguyên vẹn hết, tiền điện nước em cũng đóng đủ rồi ạ.','AM04') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L394_04','V394','房东',4,'墙面没有污渍、家电能正常使用，我全额退还押金。','qiáng miàn méi yǒu wū zì、 jiā diàn néng zhèng cháng shǐ yòng， wǒ quán é tuì huán yā jīn。','Tường không có vết bẩn, đồ điện dùng bình thường, tôi hoàn lại toàn bộ tiền cọc cho em.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L394_05','V394','阮明',5,'押金可以直接转账到我的银行卡里对吗？','yā jīn kě yǐ zhí jiē zhuǎn zhàng dào wǒ de yín háng kǎ lǐ duì ma？','Tiền cọc chuyển thẳng vào thẻ ngân hàng của em được không ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L394_06','V394','房东',6,'没问题，验收完房屋当天就给你转账。','méi wèn tí， yàn shōu wán fáng wū dàng tiān jiù gěi nǐ zhuǎn zhàng。','Không vấn đề gì, kiểm tra nhà xong hôm nay là chuyển khoản cho em luôn.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L394_07','V394','阮明',7,'辛苦您抽空过来验房，麻烦您多费心。','xīn kǔ nín chōu kòng guò lái yàn fáng， má fán nín duō fèi xīn。','Cảm ơn chủ nhà đã bỏ thời gian qua kiểm tra nhà, phiền chú/cô nhiều rồi ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT395','S119','Đóng tài khoản ngân hàng trước khi về nước',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V395','SIT395','P1','twist','chinh_thuc',NULL,'外籍人员长期离境建议注销国内闲置银行卡，避免长期休眠账户产生管理风险。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L395_01','V395','阮明',1,'您好，我即将回国，想要注销这张留学生储蓄卡。','nín hǎo， wǒ jí jiāng huí guó， xiǎng yào zhù xiāo zhè zhāng liú xué shēng chǔ xù kǎ。','Xin chào, tôi sắp về nước nên muốn đóng thẻ tiết kiệm dành cho du học sinh này.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L395_02','V395','柜员',2,'先把卡里余额全部取出，再填写销户申请单哦。','xiān bǎ kǎ lǐ yú é quán bù qǔ chū， zài tián xiě xiāo hù shēn qǐng dān ó。','Anh/chị rút hết số dư trong thẻ ra trước, sau đó điền vào đơn xin đóng tài khoản nhé.','AM03') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L395_03','V395','阮明',3,'我刚刚查询，账户还有十几块零钱没法线上转出嘛。','wǒ gāng gāng chá xún， zhàng hù hái yǒu shí jǐ kuài líng qián méi fǎ xiàn shàng zhuǎn chū ma。','Tôi vừa kiểm tra thì tài khoản vẫn còn hơn mười tệ lẻ, không rút online được.','AM09') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L395_04','V395','柜员',4,'小额现金柜台可以直接取出，不影响销户流程。','xiǎo é xiàn jīn guì tái kě yǐ zhí jiē qǔ chū， bù yǐng xiǎng xiāo hù liú chéng。','Số tiền mặt nhỏ đó có thể rút trực tiếp tại quầy, không ảnh hưởng đến việc đóng tài khoản đâu.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L395_05','V395','阮明',5,'销户完成后，银行会开具销户证明给我吗？','xiāo hù wán chéng hòu， yín háng huì kāi jù xiāo hù zhèng míng gěi wǒ ma？','Sau khi đóng tài khoản xong, ngân hàng có cấp giấy xác nhận đóng tài khoản cho tôi không?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L395_06','V395','柜员',6,'可以，纸质销户回执会加盖公章交给你留存。','kě yǐ， zhǐ zhì xiāo hù huí zhí huì jiā gài gōng zhāng jiāo gěi nǐ liú cún。','Có chứ, biên nhận đóng tài khoản bản giấy sẽ được đóng dấu và giao cho anh/chị giữ lại.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L395_07','V395','阮明',7,'好，我现在办理取现，再完成销户手续。','hǎo， wǒ xiàn zài bàn lǐ qǔ xiàn， zài wán chéng xiāo hù shǒu xù。','Vâng, giờ tôi làm thủ tục rút tiền mặt, rồi hoàn tất việc đóng tài khoản luôn.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT396','S131','Hủy SIM điện thoại trước khi về nước',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V396','SIT396','P1','suon_se','ban_chinh_thuc',NULL,'留学生离境前务必注销手机卡，若长期欠费停机，会影响本人后续再次办理国内通信业务。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L396_01','V396','阮明',1,'你好，我毕业要回国，打算注销名下这张手机电话卡。','nǐ hǎo， wǒ bì yè yào huí guó， dǎ suàn zhù xiāo míng xià zhè zhāng shǒu jī diàn huà kǎ。','Chào bạn, tôi tốt nghiệp sắp về nước rồi, tôi muốn hủy sim điện thoại đứng tên tôi.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L396_02','V396','客服',2,'出示办卡时的护照，我先查询套餐是否有未结清费用呢。','chū shì bàn kǎ shí de hù zhào， wǒ xiān chá xún tào cān shì fǒu yǒu wèi jié qīng fèi yòng ne。','Anh/chị cho em xin hộ chiếu lúc đăng ký sim, em kiểm tra xem gói cước còn nợ phí gì không nhé.','AM04') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L396_03','V396','阮明',3,'上个月话费已经缴完，没有欠费、没有合约捆绑。','shàng gè yuè huà fèi yǐ jīng jiǎo wán， méi yǒu qiàn fèi、 méi yǒu hé yuē kǔn bǎng。','Cước tháng trước tôi đóng hết rồi, không nợ cước, cũng không có ràng buộc hợp đồng gì cả.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L396_04','V396','客服',4,'那现在就能当场注销，卡里剩余话费可以现金退还。','nà xiàn zài jiù néng dāng chǎng zhù xiāo， kǎ lǐ shèng yú huà fèi kě yǐ xiàn jīn tuì huán。','Vậy thì bây giờ hủy được ngay, tiền cước còn dư trong thẻ có thể hoàn lại bằng tiền mặt.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L396_05','V396','阮明',5,'注销之后，会不会收到后续短信或者扣费通知吧？','zhù xiāo zhī hòu， huì bú huì shōu dào hòu xù duǎn xìn huò zhě kòu fèi tōng zhī ba？','Sau khi hủy sim rồi, có còn nhận được tin nhắn hay thông báo trừ tiền gì nữa không?','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L396_06','V396','客服',6,'不会，销户后号码直接回收，和你不再有关联。','bú huì， xiāo hù hòu hào mǎ zhí jiē huí shōu， hé nǐ bù zài yǒu guān lián。','Không đâu, hủy xong là số điện thoại bị thu hồi luôn, không còn liên quan gì đến anh/chị nữa.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L396_07','V396','阮明',7,'那就麻烦你帮我办理注销业务了。','nà jiù má fán nǐ bāng wǒ bàn lǐ zhù xiāo yè wù le。','Vậy thì phiền bạn giúp tôi làm thủ tục hủy sim nhé.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT397','S119','Xin hoàn lại tiền đặt cọc phòng',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V397','SIT397','P1','twist','ban_chinh_thuc',NULL,'学校各类押金退款均留存电子档案，票据丢失可凭本人有效证件核对记录办理。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L397_01','V397','阮明',1,'老师您好，我毕业离校，申请退还宿舍住宿押金。','lǎo shī nín hǎo， wǒ bì yè lí xiào， shēn qǐng tuì huán sù shè zhù sù yā jīn。','Chào thầy/cô, em tốt nghiệp rời trường rồi, em xin nộp đơn hoàn lại tiền cọc ký túc xá ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L397_02','V397','财务老师',2,'带好退房回执和缴费票据，我登记后走退款流程哈。','dài hǎo tuì fáng huí zhí hé jiǎo fèi piào jù， wǒ dēng jì hòu zǒu tuì kuǎn liú chéng hā。','Em mang theo biên nhận trả phòng và hóa đơn nộp tiền, cô ghi nhận xong sẽ làm thủ tục hoàn tiền nhé.','AM06') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L397_03','V397','阮明',3,'退房回执我带来了，但是押金票据不小心弄丢了嘛。','tuì fáng huí zhí wǒ dài lái le， dàn shì yā jīn piào jù bù xiǎo xīn nòng diū le ma。','Biên nhận trả phòng em mang rồi ạ, nhưng hóa đơn tiền cọc em lỡ làm mất mất rồi.','AM09') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L397_04','V397','财务老师',4,'没关系，系统有缴费记录，凭护照也能核对退款。','méi guān xì， xì tǒng yǒu jiǎo fèi jì lù， píng hù zhào yě néng hé duì tuì kuǎn。','Không sao, hệ thống có lưu lại thông tin nộp tiền, dùng hộ chiếu đối chiếu cũng hoàn tiền được.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L397_05','V397','阮明',5,'押金是原路退回银行卡，还是现场领取现金？','yā jīn shì yuán lù tuì huí yín háng kǎ， hái shì xiàn chǎng lǐng qǔ xiàn jīn？','Tiền cọc sẽ hoàn lại vào thẻ ngân hàng như ban đầu, hay em nhận tiền mặt tại chỗ ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L397_06','V397','财务老师',6,'统一银行卡转账，三个工作日内到账。','tǒng yī yín háng kǎ zhuǎn zhàng， sān gè gōng zuò rì nèi dào zhàng。','Đều chuyển khoản vào thẻ ngân hàng hết, trong vòng ba ngày làm việc sẽ vào tài khoản.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L397_07','V397','阮明',7,'太感谢老师帮忙核对，省去我不少麻烦。','tài gǎn xiè lǎo shī bāng máng hé duì， shěng qù wǒ bù shǎo má fán。','Em cảm ơn thầy/cô nhiều lắm vì đã giúp em đối chiếu, đỡ cho em bao nhiêu là phiền phức.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT398','S132','Làm thủ tục ra sân bay về nước',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V398','SIT398','P1','suon_se','ban_chinh_thuc',NULL,'国内国际航班充电宝只能随身携带，严禁放入托运行李，超规行李需要额外支付运费。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L398_01','V398','阮明',1,'您好，我乘坐飞往越南的航班，办理行李托运和值机。','nín hǎo， wǒ chéng zuò fēi wǎng yuè nán de háng bān， bàn lǐ xíng lǐ tuō yùn hé zhí jī。','Chào anh/chị, tôi đi chuyến bay về Việt Nam, tôi muốn ký gửi hành lý và làm thủ tục check-in.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L398_02','V398','工作人员',2,'出示你的护照和电子机票，行李不要超重哦。','chū shì nǐ de hù zhào hé diàn zi jī piào， xíng lǐ bú yào chāo zhòng ó。','Anh/chị cho em xin hộ chiếu và vé điện tử, hành lý đừng để quá cân nhé.','AM03') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L398_03','V398','阮明',3,'两件行李箱总重量二十公斤，符合免费托运标准呢。','liǎng jiàn xíng lǐ xiāng zǒng zhòng liàng èr shí gōng jīn， fú hé miǎn fèi tuō yùn biāo zhǔn ne。','Hai vali tổng cộng nặng hai mươi ký, đúng tiêu chuẩn ký gửi miễn phí rồi đó.','AM04') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L398_04','V398','工作人员',4,'行李贴好标签，登机口在二楼，提前一小时等候登机。','xíng lǐ tiē hǎo biāo qiān， dēng jī kǒu zài èr lóu， tí qián yī xiǎo shí děng hòu dēng jī。','Hành lý đã dán nhãn xong, cổng lên máy bay ở tầng hai, anh/chị ra sớm một tiếng để chờ lên máy bay nhé.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L398_05','V398','阮明',5,'随身包里有电子产品，过安检需要单独拿出来对吧？','suí shēn bāo lǐ yǒu diàn zi chǎn pǐn， guò ān jiǎn xū yào dān dú ná chū lái duì ba？','Trong túi xách tay có đồ điện tử, qua an ninh cần lấy riêng ra đúng không ạ?','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L398_06','V398','工作人员',6,'没错，电脑、充电宝都要单独过机检查。','méi cuò， diàn nǎo、 chōng diàn bǎo dōu yào dān dú guò jī jiǎn chá。','Đúng vậy, máy tính, sạc dự phòng đều phải để riêng ra để qua máy soi.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L398_07','V398','阮明',7,'清楚流程了，辛苦你指引我办理。','qīng chǔ liú chéng le， xīn kǔ nǐ zhǐ yǐn wǒ bàn lǐ。','Em hiểu quy trình rồi ạ, cảm ơn anh/chị đã hướng dẫn em làm thủ tục.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT399','S129','Xin giấy xác nhận đã hoàn thành khóa học',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V399','SIT399','P1','suon_se','ban_chinh_thuc',NULL,'海外院校会要求留学生提供课程完成证明，以此核实学生完整完成在校学习。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L399_01','V399','阮明',1,'老师，我回国升学需要课程完成证明，麻烦帮忙开具。','lǎo shī， wǒ huí guó shēng xué xū yào kè chéng wán chéng zhèng míng， má fán bāng máng kāi jù。','Thầy ơi, em về nước học tiếp cần giấy xác nhận hoàn thành khóa học, phiền thầy cấp giúp em ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L399_02','V399','教务老师',2,'所有课程、论文全部合格，才能出具这份官方证明吧。','suǒ yǒu kè chéng、 lùn wén quán bù hé gé， cái néng chū jù zhè fèn guān fāng zhèng míng ba。','Tất cả các môn học, luận văn đều phải đạt thì mới cấp được giấy xác nhận chính thức này nhé.','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L399_03','V399','阮明',3,'我的全部课程考核通过，论文也顺利答辩完成了呢。','wǒ de quán bù kè chéng kǎo hé tōng guò， lùn wén yě shùn lì dá biàn wán chéng le ne。','Tất cả các môn em đều đạt hết rồi, luận văn cũng bảo vệ thành công rồi ạ.','AM04') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L399_04','V399','教务老师',4,'我现在打印两份，加盖学院公章交给你带走。','wǒ xiàn zài dǎ yìn liǎng fèn， jiā gài xué yuàn gōng zhāng jiāo gěi nǐ dài zǒu。','Giờ tôi in hai bản, đóng dấu của khoa rồi đưa em mang đi.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L399_05','V399','阮明',5,'证明上面会标注我的在校学习时长和专业信息吗？','zhèng míng shàng miàn huì biāo zhù wǒ de zài xiào xué xí shí cháng hé zhuān yè xìn xī ma？','Trong giấy xác nhận có ghi rõ thời gian học tại trường và thông tin chuyên ngành của em không ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L399_06','V399','教务老师',6,'全部信息完整标注，国外院校完全认可。','quán bù xìn xī wán zhěng biāo zhù， guó wài yuàn xiào wán quán rèn kě。','Ghi đầy đủ hết mọi thông tin, các trường nước ngoài công nhận hoàn toàn.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L399_07','V399','阮明',7,'太感谢老师，这份证明对我的深造至关重要。','tài gǎn xiè lǎo shī， zhè fèn zhèng míng duì wǒ de shēn zào zhì guān zhòng yào。','Em cảm ơn thầy nhiều lắm, giấy xác nhận này quan trọng vô cùng với việc học tiếp của em.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT400','S133','Nói lời chia tay và cảm ơn thầy cô, bạn bè',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V400','SIT400','P1','suon_se','ban_chinh_thuc',NULL,'学生毕业离校前主动和老师当面道别是尊师礼仪，中国人习惯祝福对方前路顺遂、常保持联络。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L400_01','V400','阮明',1,'李老师，我下周就要回国了，今天特地来和您道别。','lǐ lǎo shī， wǒ xià zhōu jiù yào huí guó le， jīn tiān tè dì lái hé nín dào bié。','Cô Lý ơi, tuần sau em về nước rồi, hôm nay em đến để chào tạm biệt cô ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L400_02','V400','李老师',2,'时间过得真快，这两年你的汉语进步特别明显啊。','shí jiān guò dé zhēn kuài， zhè liǎng nián nǐ de hàn yǔ jìn bù tè bié míng xiǎn a。','Thời gian trôi nhanh thật đấy, hai năm qua tiếng Trung của em tiến bộ rõ rệt luôn.','AM05') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L400_03','V400','阮明',3,'多亏您一直耐心辅导我，我心里特别感激呢。','duō kuī nín yì zhí nài xīn fǔ dǎo wǒ， wǒ xīn lǐ tè bié gǎn jī ne。','Nhờ cô kiên nhẫn dạy dỗ em suốt thời gian qua, em cảm kích lắm ạ.','AM04') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L400_04','V400','李老师',4,'以后回国也要坚持练习汉语，有空常联系吧。','yǐ hòu huí guó yě yào jiān chí liàn xí hàn yǔ， yǒu kòng cháng lián xì ba。','Sau này về nước cũng phải duy trì luyện tiếng Trung nhé, rảnh thì thường xuyên liên lạc nha.','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L400_05','V400','阮明',5,'我回国会经常给您发消息，也会记得和同学们保持联络。','wǒ huí guó huì jīng cháng gěi nín fā xiāo xī， yě huì jì de hé tóng xué men bǎo chí lián luò。','Em về nước sẽ hay nhắn tin cho cô, cũng sẽ nhớ giữ liên lạc với các bạn nữa.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L400_06','V400','李老师',6,'一路平安，祝你回国之后一切顺利。','yí lù píng ān， zhù nǐ huí guó zhī hòu yī qiè shùn lì。','Chúc em thượng lộ bình an, mong mọi thứ suôn sẻ sau khi em về nước nhé.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L400_07','V400','阮明',7,'谢谢老师两年的照顾，我永远不会忘记这段时光。','xiè xiè lǎo shī liǎng nián de zhào gù， wǒ yǒng yuǎn bú huì wàng jì zhè duàn shí guāng。','Em cảm ơn cô đã chăm lo cho em suốt hai năm qua, em sẽ không bao giờ quên khoảng thời gian này.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT501','SV1','入境30天内前往国际学院登记备案',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V501','SIT501','P1','twist','ban_chinh_thuc',NULL,'外籍留学生入境后必须30日内完成校内住宿登记，超期会影响后续居留许可办理，甚至产生罚款。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L501_01','V501','阮明',1,'老师您好，我是新来的越南留学生，上周刚从国内入境，今天过来做入境登记备案。','lǎo shī nín hǎo ， wǒ shì xīn lái de yuè nán liú xué shēng ， shàng zhōu gāng cóng guó nèi rù jìng ， jīn tiān guò lái zuò rù jìng dēng jì bèi àn 。','Chào cô, em là du học sinh Việt Nam mới, tuần trước em vừa nhập cảnh từ trong nước, hôm nay em đến làm đăng ký nhập cảnh ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L501_02','V501','老师',2,'好的，把你的护照拿出来，还有入境时海关盖章那一页的复印件，我核对一下信息。','hǎo de ， bǎ nǐ de hù zhào ná chū lái ， hái yǒu rù jìng shí hǎi guān gài zhāng nà yī yè de fù yìn jiàn ， wǒ hé duì yī xià xìn xī 。','Được rồi, em lấy hộ chiếu ra đây, với cả bản photo trang có đóng dấu hải quan lúc nhập cảnh, cô kiểm tra lại thông tin nhé.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L501_03','V501','阮明',3,'护照我带了，盖章页……我忘记提前打印复印件了，现在没有纸质版。','hù zhào wǒ dài le ， gài zhāng yè …… wǒ wàng jì tí qián dǎ yìn fù yìn jiàn le ， xiàn zài méi yǒu zhǐ zhì bǎn 。','Hộ chiếu em có mang ạ, còn trang đóng dấu... em quên photo trước mất rồi, giờ không có bản giấy ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L501_04','V501','老师',4,'那不行，校内登记系统必须留存纸质备案材料，缺一不可。楼下就有打印店，你可以直接下去复印，很快的。','nà bù xíng ， xiào nèi dēng jì xì tǒng bì xū liú cún zhǐ zhì bèi àn cái liào ， quē yī bù kě 。 lóu xià jiù yǒu dǎ yìn diàn ， nǐ kě yǐ zhí jiē xià qù fù yìn ， hěn kuài de 。','Vậy không được đâu, hệ thống đăng ký của trường bắt buộc phải lưu hồ sơ giấy, thiếu là không được. Tầng dưới có tiệm photocopy đấy, em xuống photo luôn cũng nhanh thôi mà.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L501_05','V501','阮明',5,'好，那我现在马上下去复印。对了，回来之后还需要填别的表格吗？','hǎo ， nà wǒ xiàn zài mǎ shàng xià qù fù yìn 。 duì le ， huí lái zhī hòu hái xū yào tián bié de biǎo gé ma ？','Dạ vâng, vậy em xuống photo ngay bây giờ. À, sau khi quay lại còn phải điền thêm biểu mẫu nào khác không ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L501_06','V501','老师',6,'需要填写入境信息登记表，要写清楚你的入境日期、就读专业和宿舍具体房间号，信息必须填准确。','xū yào tián xiě rù jìng xìn xī dēng jì biǎo ， yào xiě qīng chǔ nǐ de rù jìng rì qī 、 jiù dú zhuān yè hé sù shè jù tǐ fáng jiān hào ， xìn xī bì xū tián zhǔn què 。','Cần điền tờ đăng ký thông tin nhập cảnh, phải ghi rõ ngày nhập cảnh, chuyên ngành đang học và số phòng ký túc xá cụ thể của em, thông tin phải điền chính xác nhé.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L501_07','V501','阮明',7,'了解了。是不是做完这个校内登记，才能去出入境大厅办理居留许可？','liǎo jiě le 。 shì bú shì zuò wán zhè ge xiào nèi dēng jì ， cái néng qù chū rù jìng dà tīng bàn lǐ jū liú xǔ kě ？','Em hiểu rồi ạ. Có phải làm xong đăng ký trong trường này thì mới có thể đến sảnh xuất nhập cảnh làm thủ tục giấy phép cư trú không ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L501_08','V501','老师',8,'没错，这是前置流程。没完成校内住宿入境登记，出入境那边是直接不受理你的签证业务的。','méi cuò ， zhè shì qián zhì liú chéng 。 méi wán chéng xiào nèi zhù sù rù jìng dēng jì ， chū rù jìng nà biān shì zhí jiē bù shòu lǐ nǐ de qiān zhèng yè wù de 。','Đúng vậy, đây là bước bắt buộc trước đó. Nếu chưa hoàn thành đăng ký lưu trú nhập cảnh trong trường thì bên xuất nhập cảnh sẽ không tiếp nhận hồ sơ visa của em đâu.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L501_09','V501','阮明',9,'原来是这样，还好我提前来办理了。我十分钟就能回来，马上办好登记。','yuán lái shì zhè yàng ， hái hǎo wǒ tí qián lái bàn lǐ le 。 wǒ shí fēn zhōng jiù néng huí lái ， mǎ shàng bàn hǎo dēng jì 。','Ra là vậy, may mà em đến làm sớm. Em mười phút nữa sẽ quay lại, làm xong đăng ký ngay ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT502','SV1','提交护照、录取材料申请首次居留许可',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V502','SIT502','P1','suon_se','chinh_thuc',NULL,'首次学生居留许可全套材料缺一不可，缺少任意一项都会直接退回不予受理。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_01','V502','阮明',1,'您好，我是今年的新生留学生，过来申请办理首次学生居留许可。','nín hǎo ， wǒ shì jīn nián de xīn shēng liú xué shēng ， guò lái shēn qǐng bàn lǐ shǒu cì xué shēng jū liú xǔ kě 。','Chào chị, em là tân sinh viên du học năm nay, em đến xin làm thủ tục cấp giấy phép cư trú lần đầu ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_02','V502','工作人员',2,'可以的，把所需材料依次递过来，护照、录取通知书、体检报告、住宿登记单，全部都要。','kě yǐ de ， bǎ suǒ xū cái liào yī cì dì guò lái ， hù zhào 、 lù qǔ tōng zhī shū 、 tǐ jiǎn bào gào 、 zhù sù dēng jì dān ， quán bù dōu yào 。','Được, em đưa lần lượt các giấy tờ cần thiết ra đây, hộ chiếu, giấy báo nhập học, giấy khám sức khỏe, phiếu đăng ký lưu trú, tất cả đều cần cả.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_03','V502','阮明',3,'好的，我都提前整理好了，一式两份，您直接核对就行。','hǎo de ， wǒ dōu tí qián zhěng lǐ hǎo le ， yī shì liǎng fèn ， nín zhí jiē hé duì jiù xíng 。','Dạ, em đã chuẩn bị sẵn hết rồi ạ, mỗi loại hai bản, chị kiểm tra trực tiếp là được ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_04','V502','工作人员',4,'我逐一核对一下……信息全部匹配，材料齐全没有问题，这是你的受理回执，你收好。','wǒ zhú yī hé duì yī xià …… xìn xī quán bù pǐ pèi ， cái liào qí quán méi yǒu wèn tí ， zhè shì nǐ de shòu lǐ huí zhí ， nǐ shōu hǎo 。','Để chị kiểm tra từng cái một nhé... thông tin khớp hết rồi, giấy tờ đầy đủ không có vấn đề gì, đây là biên nhận tiếp nhận hồ sơ của em, em giữ cẩn thận nhé.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_05','V502','阮明',5,'好的，谢谢！我想问一下，大概多久能办好拿到居留贴纸？','hǎo de ， xiè xiè ！ wǒ xiǎng wèn yī xià ， dà gài duō jiǔ néng bàn hǎo ná dào jū liú tiē zhǐ ？','Dạ vâng, cảm ơn chị! Cho em hỏi, khoảng bao lâu thì em nhận được thẻ cư trú ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_06','V502','工作人员',6,'普通办理是七个工作日，要是着急的话，可以申请加急，三个工作日就能办结。','pǔ tōng bàn lǐ shì qī gè gōng zuò rì ， yào shì zháo jí de huà ， kě yǐ shēn qǐng jiā jí ， sān gè gōng zuò rì jiù néng bàn jié 。','Xử lý thông thường là bảy ngày làm việc, nếu gấp thì có thể đăng ký làm nhanh, ba ngày làm việc là xong.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_07','V502','阮明',7,'了解了。那取件可以让人代领吗？还是必须我本人过来？','liǎo jiě le 。 nà qǔ jiàn kě yǐ ràng rén dài lǐng ma ？ hái shì bì xū wǒ běn rén guò lái ？','Em hiểu rồi ạ. Vậy lúc lấy thẻ có thể nhờ người khác lấy hộ được không hay bắt buộc em phải đến trực tiếp ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_08','V502','工作人员',8,'必须本人携带回执和护照原件到场领取，不支持代领。','bì xū běn rén xié dài huí zhí hé hù zhào yuán jiàn dào chǎng lǐng qǔ ， bù zhī chí dài lǐng 。','Bắt buộc phải chính chủ mang biên nhận và hộ chiếu gốc đến lấy trực tiếp, không hỗ trợ nhờ người khác lấy hộ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_09','V502','阮明',9,'好，我清楚所有流程了，麻烦您帮忙受理啦！','hǎo ， wǒ qīng chǔ suǒ yǒu liú chéng le ， má fán nín bāng máng shòu lǐ la ！','Dạ, em nắm rõ hết quy trình rồi, phiền chị giúp em xử lý hồ sơ nhé ạ!','AM02') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT503','SV1','体检不合格，需要重新预约出入境体检',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V503','SIT503','P1','that_bai_nhe','ban_chinh_thuc',NULL,'留学生签证专用体检必须在出入境指定医院完成，体检不合格无法提交居留申请，复查需全额自费。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_01','V503','阮明',1,'医生，我刚拿到出入境的体检报告，显示不合格，办不了签证。','yī shēng ， wǒ gāng ná dào chū rù jìng de tǐ jiǎn bào gào ， xiǎn shì bù hé gé ， bàn bù liǎo qiān zhèng 。','Bác sĩ ơi, em vừa nhận được báo cáo khám sức khỏe xuất nhập cảnh, kết quả không đạt, không làm visa được ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_02','V503','校医',2,'我看一下报告。嗯，主要是肝功能指标偏高，属于临时异常，不符合签证体检的合格标准。','wǒ kàn yī xià bào gào 。 ń ， zhǔ yào shì gān gōng néng zhǐ biāo piān gāo ， shǔ yú lín shí yì cháng ， bù fú hé qiān zhèng tǐ jiǎn de hé gé biāo zhǔn 。','Để bác xem báo cáo nào. Ừm, chủ yếu là chỉ số chức năng gan hơi cao, thuộc dạng bất thường tạm thời, không đạt tiêu chuẩn khám sức khỏe cho visa.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_03','V503','阮明',3,'啊？那能不能只单独复查这一项？不用全套重新查吧？','a ？ nà néng bù néng zhǐ dān dú fù chá zhè yī xiàng ？ bù yòng quán tào chóng xīn chá ba ？','Hả? Vậy có thể chỉ khám lại riêng mục này thôi không ạ? Không cần khám lại toàn bộ chứ ạ?','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_04','V503','校医',4,'不行的，出入境中心有规定，单项异常不支持单独复查。','bù xíng de ， chū rù jìng zhōng xīn yǒu guī dìng ， dān xiàng yì cháng bù zhī chí dān dú fù chá 。','Không được đâu, trung tâm xuất nhập cảnh có quy định, bất thường ở một mục thì không được khám lại riêng lẻ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_05','V503','阮明',5,'这样啊……那我现在该怎么办？','zhè yàng a …… nà wǒ xiàn zài gāi zěn me bàn ？','Vậy à... vậy giờ em phải làm sao ạ?','AM05') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_06','V503','校医',6,'你接下来一周清淡饮食、别熬夜、不喝酒，一周之后再来重新预约全套体检。','nǐ jiē xià lái yī zhōu qīng dàn yǐn shí 、 bié áo yè 、 bù hē jiǔ ， yī zhōu zhī hòu zài lái chóng xīn yù yuē quán tào tǐ jiǎn 。','Em về ăn uống thanh đạm trong một tuần tới, đừng thức khuya, đừng uống rượu bia, một tuần sau quay lại đặt lịch khám lại toàn bộ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_07','V503','阮明',7,'重新全套体检的话，是不是要重新交一整套费用？','chóng xīn quán tào tǐ jiǎn de huà ， shì bú shì yào chóng xīn jiāo yī zhěng tào fèi yòng ？','Nếu khám lại toàn bộ thì em có phải đóng lại toàn bộ chi phí không ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_08','V503','校医',8,'对的，复查没有减免，必须全额缴费，和第一次体检流程一样。','duì de ， fù chá méi yǒu jiǎn miǎn ， bì xū quán é jiǎo fèi ， hé dì yī cì tǐ jiǎn liú chéng yī yàng 。','Đúng vậy, khám lại không được giảm trừ gì cả, phải đóng đủ phí, quy trình giống hệt lần khám đầu tiên.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_09','V503','阮明',9,'我明白了。那我一周后直接在网上预约就行？','wǒ míng bái le 。 nà wǒ yī zhōu hòu zhí jiē zài wǎng shàng yù yuē jiù xíng ？','Em hiểu rồi ạ. Vậy một tuần sau em đặt lịch trực tiếp trên mạng là được đúng không ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_10','V503','校医',10,'可以线上预约，过来的时候把这次不合格的报告带上，方便医生对比数据，排除持续性异常。','kě yǐ xiàn shàng yù yuē ， guò lái de shí hòu bǎ zhè cì bù hé gé de bào gào dài shàng ， fāng biàn yī shēng duì bǐ shù jù ， pái chú chí xù xìng yì cháng 。','Có thể đặt lịch online, lúc đến thì mang theo báo cáo không đạt lần này, để bác sĩ tiện đối chiếu số liệu, loại trừ trường hợp bất thường kéo dài.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_11','V503','阮明',11,'好，那我这几天好好调整作息，一周后再来重新体检。','hǎo ， nà wǒ zhè jǐ tiān hǎo hǎo tiáo zhěng zuò xī ， yī zhōu hòu zài lái chóng xīn tǐ jiǎn 。','Dạ vâng, vậy mấy ngày tới em sẽ điều chỉnh sinh hoạt cho tốt, một tuần sau em quay lại khám lại ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT504','SV1','忘记携带境外录取通知书原件，无法提交签证材料',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V504','SIT504','P1','that_bai_nhe','chinh_thuc',NULL,'出入境办理居留许可严格核验纸质原件，电子照片、复印件均不具备受理效力，必须线下现场核验。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_01','V504','阮明',1,'您好，我来提交居留许可的申请材料，麻烦您帮我审核一下。','nín hǎo ， wǒ lái tí jiāo jū liú xǔ kě de shēn qǐng cái liào ， má fán nín bāng wǒ shěn hé yī xià 。','Chào chị, em đến nộp hồ sơ xin giấy phép cư trú, phiền chị kiểm tra giúp em ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_02','V504','工作人员',2,'好的，请出示你的境外录取通知书原件。','hǎo de ， qǐng chū shì nǐ de jìng wài lù qǔ tōng zhī shū yuán jiàn 。','Được, em cho chị xem bản gốc giấy báo nhập học ở nước ngoài của em nhé.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_03','V504','阮明',3,'糟了……我只带了复印件，原件落在宿舍了，忘记拿过来。','zāo le …… wǒ zhǐ dài le fù yìn jiàn ， yuán jiàn luò zài sù shè le ， wàng jì ná guò lái 。','Chết rồi... em chỉ mang bản photo thôi, bản gốc để quên ở ký túc xá, em quên mang theo mất rồi.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_04','V504','工作人员',4,'抱歉，签证审核必须核验纸质原件，复印件是无效的，不能受理。','bào qiàn ， qiān zhèng shěn hé bì xū hé yàn zhǐ zhì yuán jiàn ， fù yìn jiàn shì wú xiào de ， bù néng shòu lǐ 。','Xin lỗi em, khâu xét duyệt visa bắt buộc phải kiểm tra bản gốc giấy tờ, bản photo không có giá trị, chị không thể tiếp nhận được.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_05','V504','阮明',5,'那能不能通融一下？我手机里有原件的高清照片，先帮我建档，我明天马上补交原件可以吗？','nà néng bù néng tōng róng yī xià ？ wǒ shǒu jī lǐ yǒu yuán jiàn de gāo qīng zhào piān ， xiān bāng wǒ jiàn dàng ， wǒ míng tiān mǎ shàng bǔ jiāo yuán jiàn kě yǐ ma ？','Vậy có thể châm chước một chút được không ạ? Trong điện thoại em có ảnh chụp bản gốc độ phân giải cao, chị giúp em lập hồ sơ trước, mai em bổ sung bản gốc ngay được không ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_06','V504','工作人员',6,'不行的，这是系统硬性规定。材料不齐没办法录入系统建档，只能改天带齐原件再来办理。','bù xíng de ， zhè shì xì tǒng yìng xìng guī dìng 。 cái liào bù qí méi bàn fǎ lù rù xì tǒng jiàn dàng ， zhǐ néng gǎi tiān dài qí yuán jiàn zài lái bàn lǐ 。','Không được đâu em, đây là quy định cứng của hệ thống. Hồ sơ chưa đủ thì không thể nhập vào hệ thống để lập hồ sơ được, chỉ có thể hôm khác mang đủ bản gốc rồi đến làm lại thôi.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_07','V504','阮明',7,'我明白了。那我明天一早过来可以吗？','wǒ míng bái le 。 nà wǒ míng tiān yī zǎo guò lái kě yǐ ma ？','Em hiểu rồi ạ. Vậy mai sáng sớm em qua được không ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_08','V504','工作人员',8,'可以，我们明天正常上班。建议你早点来，上午号源比较充足，不用久等。','kě yǐ ， wǒ men míng tiān zhèng cháng shàng bān 。 jiàn yì nǐ zǎo diǎn lái ， shàng wǔ hào yuán bǐ jiào chōng zú ， bù yòng jiǔ děng 。','Được chứ, mai chúng tôi làm việc bình thường. Chị khuyên em đến sớm một chút, buổi sáng số thứ tự còn nhiều, không phải chờ lâu đâu.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
